nd\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"events.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"events.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"extensions\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"flowcontrol.apiserver.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"flowcontrol.apiserver.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"flowcontrol.apiserver.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta2\"},{\"group\":\"flowcontrol.apiserver.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta3\"},{\"group\":\"imagepolicy.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"internal.apiserver.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"networking.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"networking.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"node.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"node.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"node.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"policy\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"policy\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"rbac.authorization.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"rbac.authorization.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"rbac.authorization.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"resource.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"resource.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha3\"},{\"group\":\"resource.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"resource.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta2\"},{\"group\":\"scheduling.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"scheduling.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"scheduling.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"storage.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1\"},{\"group\":\"storage.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1alpha1\"},{\"group\":\"storage.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"},{\"group\":\"storagemigration.k8s.io\",\"kind\":\"WatchEvent\",\"version\":\"v1beta1\"}]},\"io.k8s.apimachinery.pkg.runtime.RawExtension\":{\"description\":\"RawExtension is used to hold extensions in external versions.\\n\\nTo use this, make a field which has RawExtension as its type in your external, versioned struct, and Object in your internal struct. You also need to register your various plugin types.\\n\\n// Internal package:\\n\\n\\ttype MyAPIObject struct {\\n\\t\\truntime.TypeMeta `json:\\\",inline\\\"`\\n\\t\\tMyPlugin runtime.Object `json:\\\"myPlugin\\\"`\\n\\t}\\n\\n\\ttype PluginA struct {\\n\\t\\tAOption string `json:\\\"aOption\\\"`\\n\\t}\\n\\n// External package:\\n\\n\\ttype MyAPIObject struct {\\n\\t\\truntime.TypeMeta `json:\\\",inline\\\"`\\n\\t\\tMyPlugin runtime.RawExtension `json:\\\"myPlugin\\\"`\\n\\t}\\n\\n\\ttype PluginA struct {\\n\\t\\tAOption string `json:\\\"aOption\\\"`\\n\\t}\\n\\n// On the wire, the JSON will look something like this:\\n\\n\\t{\\n\\t\\t\\\"kind\\\":\\\"MyAPIObject\\\",\\n\\t\\t\\\"apiVersion\\\":\\\"v1\\\",\\n\\t\\t\\\"myPlugin\\\": {\\n\\t\\t\\t\\\"kind\\\":\\\"PluginA\\\",\\n\\t\\t\\t\\\"aOption\\\":\\\"foo\\\",\\n\\t\\t},\\n\\t}\\n\\nSo what happens? Decode first uses json or yaml to unmarshal the serialized data into your external MyAPIObject. That causes the raw JSON to be stored, but not unpacked. The next step is to copy (using pkg/conversion) into the internal struct. The runtime package's DefaultScheme has conversion functions installed which will unpack the JSON stored in RawExtension, turning it into the correct object type, and storing it in the Object. (TODO: In the case where the object is of an unknown type, a runtime.Unknown object will be created and stored.)\",\"type\":\"object\"},\"io.k8s.apimachinery.pkg.apis.meta.v1.JSONPatch\":{\"description\":\"A JSON Patch document (RFC 6902): the sequence of operations to apply to the target object.\",\"type\":\"array\",\"items\":{\"type\":\"object\"}}},\"securitySchemes\":{\"BearerToken\":{\"description\":\"Bearer Token authentication\",\"in\":\"header\",\"name\":\"authorization\",\"type\":\"apiKey\"}}},\"info\":{\"title\":\"Kubernetes\",\"version\":\"unversioned\"},\"openapi\":\"3.0.0\",\"paths\":{\"/apis/apiextensions.k8s.io/v1/\":{\"get\":{\"description\":\"get available resources\",\"operationId\":\"getApiextensionsV1APIResources\",\"responses\":{\"200\":{\"content\":{\"application/cbor\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-3f1064af2ac2d3ed89fa.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.APIResourceList\"}},\"application/json\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-3f1064af2ac2d3ed89fa.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.APIResourceList\"}},\"application/vnd.kubernetes.protobuf\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-3f1064af2ac2d3ed89fa.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.APIResourceList\"}},\"application/yaml\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-3f1064af2ac2d3ed89fa.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.APIResourceList\"}}},\"description\":\"OK\"},\"401\":{\"description\":\"Unauthorized\"}},\"tags\":[\"apiextensions_v1\"]}},\"/apis/apiextensions.k8s.io/v1/customresourcedefinitions\":{\"delete\":{\"description\":\"delete collection of CustomResourceDefinition\",\"operationId\":\"deleteApiextensionsV1CollectionCustomResourceDefinition\",\"parameters\":[{\"description\":\"The continue option should be set when retrieving more results from the server. Since this value is server defined, clients may only use the continue value from a previous query result with identical query parameters (except for the value of continue) and the server may reject a continue value it does not recognize. If the specified continue value is no longer valid whether due to expiration (generally five to fifteen minutes) or a configuration change on the server, the server will respond with a 410 ResourceExpired error together with a continue token. If the client needs a consistent list, it must restart their list without the continue field. Otherwise, the client may send another list request with the token received with the 410 error, the server will respond with a list starting from the next key, but from the latest snapshot, which is inconsistent from the previous list results - objects that are created, modified, or deleted after the first list request will be included in the response, as long as their keys are after the \\\"next key\\\".\\n\\nThis field is not supported when watch is true. Clients may start a watch from the last resourceVersion value returned by the server and not miss any modifications.\",\"in\":\"query\",\"name\":\"continue\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"When present, indicates that modifications should not be persisted. An invalid or unrecognized dryRun directive will result in an error response and no further processing of the request. Valid values are: - All: all dry run stages will be processed\",\"in\":\"query\",\"name\":\"dryRun\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"A selector to restrict the list of returned objects by their fields. Defaults to everything.\",\"in\":\"query\",\"name\":\"fieldSelector\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"The duration in seconds before the object should be deleted. Value must be non-negative integer. The value zero indicates delete immediately. If this value is nil, the default grace period for the specified type will be used. Defaults to a per object value if not specified. zero means delete immediately.\",\"in\":\"query\",\"name\":\"gracePeriodSeconds\",\"schema\":{\"type\":\"integer\",\"uniqueItems\":true}},{\"description\":\"if set to true, it will trigger an unsafe deletion of the resource in case the normal deletion flow fails with a corrupt object error. A resource is considered corrupt if it can not be retrieved from the underlying storage successfully because of a) its data can not be transformed e.g. decryption failure, or b) it fails to decode into an object. NOTE: unsafe deletion ignores finalizer constraints, skips precondition checks, and removes the object from the storage. WARNING: This may potentially break the cluster if the workload associated with the resource being unsafe-deleted relies on normal deletion flow. Use only if you REALLY know what you are doing. The default value is false, and the user must opt in to enable it\",\"in\":\"query\",\"name\":\"ignoreStoreReadErrorWithClusterBreakingPotential\",\"schema\":{\"type\":\"boolean\",\"uniqueItems\":true}},{\"description\":\"A selector to restrict the list of returned objects by their labels. Defaults to everything.\",\"in\":\"query\",\"name\":\"labelSelector\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"limit is a maximum number of responses to return for a list call. If more items exist, the server will set the `continue` field on the list metadata to a value that can be used with the same initial query to retrieve the next set of results. Setting a limit may return fewer than the requested amount of items (up to zero items) in the event all requested objects are filtered out and clients should only use the presence of the continue field to determine whether more results are available. Servers may choose not to support the limit argument and will return all of the available results. If limit is specified and the continue field is empty, clients may assume that no more results are available. This field is not supported if watch is true.\\n\\nThe server guarantees that the objects returned when using continue will be identical to issuing a single list call without a limit - that is, no objects created, modified, or deleted after the first request is issued will be included in any subsequent continued requests. This is sometimes referred to as a consistent snapshot, and ensures that a client that is using limit to receive smaller chunks of a very large result can ensure they see all possible objects. If objects are updated during a chunked list the version of the object that was present at the time the first list result was calculated is returned.\",\"in\":\"query\",\"name\":\"limit\",\"schema\":{\"type\":\"integer\",\"uniqueItems\":true}},{\"description\":\"Deprecated: please use the PropagationPolicy, this field will be deprecated in 1.7. Should the dependent objects be orphaned. If true/false, the \\\"orphan\\\" finalizer will be added to/removed from the object's finalizers list. Either this field or PropagationPolicy may be set, but not both.\",\"in\":\"query\",\"name\":\"orphanDependents\",\"schema\":{\"type\":\"boolean\",\"uniqueItems\":true}},{\"description\":\"Whether and how garbage collection will be performed. Either this field or OrphanDependents may be set, but not both. The default policy is decided by the existing finalizer set in the metadata.finalizers and the resource-specific default policy. Acceptable values are: 'Orphan' - orphan the dependents; 'Background' - allow the garbage collector to delete the dependents in the background; 'Foreground' - a cascading policy that deletes all dependents in the foreground.\",\"in\":\"query\",\"name\":\"propagationPolicy\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"resourceVersion sets a constraint on what resource versions a request may be served from. See https://kubernetes.io/docs/reference/using-api/api-concepts/#resource-versions for details.\\n\\nDefaults to unset\",\"in\":\"query\",\"name\":\"resourceVersion\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"resourceVersionMatch determines how resourceVersion is applied to list calls. It is highly recommended that resourceVersionMatch be set for list calls where resourceVersion is set See https://kubernetes.io/docs/reference/using-api/api-concepts/#resource-versions for details.\\n\\nDefaults to unset\",\"in\":\"query\",\"name\":\"resourceVersionMatch\",\"schema\":{\"type\":\"string\",\"uniqueItems\":true}},{\"description\":\"`sendInitialEvents=true` may be set together with `watch=true`. In that case, the watch stream will begin with synthetic events to produce the current state of objects in the collection. Once all such events have been sent, a synthetic \\\"Bookmark\\\" event  will be sent. The bookmark will report the ResourceVersion (RV) corresponding to the set of objects, and be marked with `\\\"k8s.io/initial-events-end\\\": \\\"true\\\"` annotation. Afterwards, the watch stream will proceed as usual, sending watch events corresponding to changes (subsequent to the RV) to objects watched.\\n\\nWhen `sendInitialEvents` option is set, we require `resourceVersionMatch` option to also be set. The semantic of the watch request is as following: - `resourceVersionMatch` = NotOlderThan\\n  is interpreted as \\\"data at least as new as the provided `resourceVersion`\\\"\\n  and the bookmark event is send when the state is synced\\n  to a `resourceVersion` at least as fresh as the one provided by the ListOptions.\\n  If `resourceVersion` is unset, this is interpreted as \\\"consistent read\\\" and the\\n  bookmark event is send when the state is synced at least to the moment\\n  when request started being processed.\\n- `resourceVersionMatch` set to any other value or unset\\n  Invalid error is returned.\\n\\nDefaults to true if `resourceVersion=\\\"\\\"` or `resourceVersion=\\\"0\\\"` (for backward compatibility reasons) and to false otherwise.\",\"in\":\"query\",\"name\":\"sendInitialEvents\",\"schema\":{\"type\":\"boolean\",\"uniqueItems\":true}},{\"description\":\"Timeout for the list/watch call. This limits the duration of the call, regardless of any activity or inactivity.\",\"in\":\"query\",\"name\":\"timeoutSeconds\",\"schema\":{\"type\":\"integer\",\"uniqueItems\":true}}],\"requestBody\":{\"content\":{\"application/json\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-3f1064af2ac2d3ed89fa.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.DeleteOptions\"}}}},\"responses\":{\"200\":{\"content\":{\"application/cbor\":{\"schema\":{}},\"application/json\":{\"schema\":{}},\"application/vnd.kubernetes.protobuf\":{\"schema\":{}},\"application/yaml\":{\"schema\":{}}},\"description\":\"OK\"},\"401\":{\"description\":\"Unauthorized\"}},\"tags\":[\"apiextensions_v1\"],\"x-kubernetes-action\":\"deletecollection\",\"x-kubernetes-group-version-kind\":{\"group\":\"apiextensions.k8s.io\",\"kind\":\"CustomResourceDefinition\",\"version\":\"v1\"}},\"get\":{\"description\":\"list or watch objects of kind CustomResourceDefinition\",\"operationId\":\"listApiextensionsV1CustomResourceDefinition\",\"parameters\":[{\"description\":\"allowWatchBookmarks requests watch events with type \\\"BOOKMARK\\\". Servers that do not implement bookmarks may ignore this flag and bookmarks are sent at the server's discretion. Clients should not assume bookmarks are returned at any specific interval, nor may they assume the server will send any BOOKMARK event during a session. If this is not a watch, this field is ignored.\",\"in\":\"query\",\"name\":\"allowWatchBookmarks\",\"schema\":{\"type\":\"boolean\",\"uniqueItems\":true}},{\"description\":\"The continue option should be set when retrieving more results from the server. Since this value is server defined, clients may only use the continue value from a previous query result w